-- KHUNYUI DATABASE 002 — V50 LOCKED MASTER SEED
-- Exact 120 menu rows are sourced from CUSTOMER V50.

begin;
on conflict(id) do update set store_name=excluded.store_name,branch=excluded.branch,timezone=excluded.timezone;

on conflict(store_id) do nothing;

on conflict(token) do update set active=true,label=excluded.label;

on conflict(store_id,code) do update set
 cat=excluded.cat, subcategory=excluded.subcategory, category=excluded.category,
 name=excluded.name, price=excluded.price, legacy_image_path=excluded.legacy_image_path, sort_order=excluded.sort_order;

commit;
